    def website_form_backup_enabled(self) -> bool:
        return self.safe_bool(self.options, 'websiteFormBackup', False)

    def ensure_website_user_agent(self):
        if not self.website_form_backup_enabled():
            return
        browserUserAgent = self.safe_string(self.options, 'websiteFormUserAgent')
        if browserUserAgent is None:
            return
        if self.userAgent != browserUserAgent:
            self.userAgent = browserUserAgent

    def wizardswap_order_page_url(self, id: str) -> str:
        www = self.safe_string(self.urls, 'www', 'https://www.wizardswap.io')
        base = www if www.endswith('/') else www + '/'
        return base + 'id=' + id

    def website_index_of_insensitive(self, haystack: str, needle: str) -> float:
        return haystack.lower().find(needle.lower())

    def website_trim_left(self, text: str) -> str:
        startIndex = 0
        while(startIndex < len(text)):
            character = text[startIndex]
            if character == ' ' or character == '\t' or character == '\n' or character == '\r':
                startIndex += 1
            else:
                break
        return text[startIndex:]

    def website_leading_alphanumeric_id(self, text: str) -> Str:
        id = ''
        for charIndex in range(0, len(text)):
            character = text[charIndex]
            isUpper = (character >= 'A' and character <= 'Z')
            isDigit = (character >= '0' and character <= '9')
            if isUpper or isDigit:
                id += character
            elif len(id) > 0:
                break
        if id == '':
            return None
        return id

    def parse_website_csrf_token(self, html: str) -> str:
        tokenField = 'name="token"'
        fieldIndex = html.find(tokenField)
        if fieldIndex < 0:
            raise InvalidOrder(self.id + ' createOrder() failed: homepage has no CSRF token')
        chunk = html[fieldIndex:fieldIndex + 120]
        valueMarker = 'value="'
        valueIndex = chunk.find(valueMarker)
        if valueIndex < 0:
            raise InvalidOrder(self.id + ' createOrder() failed: homepage has no CSRF token')
        afterValue = chunk[valueIndex + len(valueMarker):]
        endQuote = afterValue.find('"')
        if endQuote < 0:
            raise InvalidOrder(self.id + ' createOrder() failed: homepage has no CSRF token')
        return afterValue[0:endQuote]

    def parse_website_create_order_id(self, responseOrError: Any) -> str:
        candidates = []
        if isinstance(responseOrError, str):
            candidates.append(responseOrError)
        elif responseOrError is not None:
            message = self.safe_string(responseOrError, 'message')
            if message is not None:
                candidates.append(message)
        redirectNeedle = 'redirect to id='
        exchangeIdNeedle = 'Exchange ID:'
        for i in range(0, len(candidates)):
            text = candidates[i]
            redirectIndex = self.website_index_of_insensitive(text, redirectNeedle)
            if redirectIndex >= 0:
                afterRedirect = text[redirectIndex + len(redirectNeedle):]
                orderId = self.website_leading_alphanumeric_id(afterRedirect)
                if orderId is not None:
                    return orderId
            exchangeIdIndex = self.website_index_of_insensitive(text, exchangeIdNeedle)
            if exchangeIdIndex >= 0:
                afterLabel = text[exchangeIdIndex + len(exchangeIdNeedle):]
                orderId = self.website_leading_alphanumeric_id(self.website_trim_left(afterLabel))
                if orderId is not None:
                    return orderId
        raise InvalidOrder(self.id + ' createOrder() failed: exchange response has no order id')

    def parse_website_status_text(self, statusText: Str) -> Str:
        if statusText is None:
            return None
        lowered = statusText.strip().lower()
        if lowered.startswith('waiting'):
            return 'waiting'
        if lowered.startswith('confirming'):
            return 'confirming'
        if lowered.startswith('exchanging'):
            return 'exchanging'
        if lowered.startswith('sending'):
            return 'sending'
        if lowered.startswith('completed') or lowered.startswith('finished'):
            return 'finished'
        if lowered.startswith('failed'):
            return 'failed'
        if lowered.startswith('refunded'):
            return 'refunded'
        if lowered.startswith('verifying'):
            return 'verifying'
        return None

    def parse_website_html_field(self, html: str, fieldId: str) -> Str:
        idMarker = 'id="' + fieldId + '"'
        fieldIndex = html.find(idMarker)
        if fieldIndex < 0:
            return None
        chunk = html[fieldIndex:fieldIndex + 400]
        tagEnd = chunk.find('>')
        valueMarker = 'value="'
        valueIndex = chunk.find(valueMarker)
        if valueIndex >= 0 and (tagEnd < 0 or valueIndex < tagEnd):
            afterValue = chunk[valueIndex + len(valueMarker):]
            endQuote = afterValue.find('"')
            if endQuote >= 0:
                value = afterValue[0:endQuote].strip()
                if value == '':
                    return None
                return value
        if tagEnd < 0:
            return None
        inner = chunk[tagEnd + 1:]
        closeTag = inner.find('<')
        if closeTag < 0:
            return None
        text = inner[0:closeTag].strip()
        if text == '':
            return None
        return text

    def parse_website_status_heading(self, html: str) -> Str:
        marker = '<h2 id="status"'
        markerIndex = html.find(marker)
        if markerIndex < 0:
            return None
        chunk = html[markerIndex:markerIndex + 200]
        tagEnd = chunk.find('>')
        if tagEnd < 0:
            return None
        inner = chunk[tagEnd + 1:]
        closeTag = inner.find('<')
        if closeTag < 0:
            return None
        return inner[0:closeTag].strip()

    def parse_website_minimum_currency(self, html: str) -> Str:
        label = 'Minimum '
        labelIndex = html.find(label)
        if labelIndex < 0:
            return None
        rest = html[labelIndex + len(label):]
        currency = ''
        for charIndex in range(0, len(rest)):
            character = rest[charIndex]
            if character >= 'A' and character <= 'Z':
                currency += character
            else:
                break
        if currency == '':
            return None
        return currency.lower()

    def parse_website_amount_to_be_sent(self, html: str) -> dict:
        label = 'Amount to be sent:'
        labelIndex = html.find(label)
        if labelIndex < 0:
            return None
        rest = self.website_trim_left(html[labelIndex + len(label):])
        amount = ''
        amountEndIndex = 0
        for charIndex in range(0, len(rest)):
            character = rest[charIndex]
            if (character >= '0' and character <= '9') or character == '.':
                amount += character
                amountEndIndex = charIndex + 1
            else:
                break
        currency = ''
        afterAmount = self.website_trim_left(rest[amountEndIndex:])
        for charIndex in range(0, len(afterAmount)):
            character = afterAmount[charIndex]
            if character >= 'A' and character <= 'Z':
                currency += character
            else:
                break
        if amount == '' or currency == '':
            return None
        return {
            'amount_to': amount,
            'currency_to': currency.lower(),
        }

    async def fetch_website_order_page(self, id: str) -> dict:
        html = await self.fetch(self.wizardswap_order_page_url(id), 'GET', None, None)
        if not isinstance(html, str):
            raise ExchangeError(self.id + ' unexpected order page response type')
        exchangeIdLabel = 'Exchange ID: ' + id
        if html.find(exchangeIdLabel) < 0 and html.find(id) < 0:
            raise OrderNotFound(self.id + ' order ' + id + ' not found')
        exchangeIdNeedle = 'Exchange ID:'
        exchangeIdIndex = self.website_index_of_insensitive(html, exchangeIdNeedle)
        parsedId = id
        if exchangeIdIndex >= 0:
            afterLabel = html[exchangeIdIndex + len(exchangeIdNeedle):]
            pageId = self.website_leading_alphanumeric_id(self.website_trim_left(afterLabel))
            if pageId is not None:
                parsedId = pageId
        if parsedId != id:
            raise ExchangeError(self.id + ' order page id mismatch')
        statusText = self.parse_website_status_heading(html)
        amountToPart = self.parse_website_amount_to_be_sent(html)
        currencyFrom = self.parse_website_minimum_currency(html)
        page = {
            'id': parsedId,
            'status_text': statusText,
            'amount_from': self.parse_website_html_field(html, 'amount_a'),
            'address_from': self.parse_website_html_field(html, 'deposit_address'),
            'address_to': self.parse_website_html_field(html, 'receiver_address'),
        }
        if currencyFrom is not None:
            page['currency_from'] = currencyFrom
        if amountToPart is not None:
            page['amount_to'] = amountToPart['amount_to']
            page['currency_to'] = amountToPart['currency_to']
        return page

    def normalize_website_order(self, raw: dict, market: Market = None) -> dict:
        status = self.safe_string(raw, 'status')
        if status is None:
            status = self.parse_website_status_text(self.safe_string(raw, 'status_text'))
        currencyFrom = self.safe_string(raw, 'currency_from')
        currencyTo = self.safe_string(raw, 'currency_to')
        if market is not None:
            if currencyFrom is None:
                currencyFrom = self.safe_string(market, 'baseId')
            if currencyTo is None:
                currencyTo = self.safe_string(market, 'quoteId')
        amountFrom = self.safe_string_2(raw, 'amount_from', 'expected_amount')
        amountTo = self.safe_string(raw, 'amount_to')
        normalized = {
            'id': self.safe_string(raw, 'id'),
            'status': status,
            'currency_from': currencyFrom,
            'currency_to': currencyTo,
            'amount_from': amountFrom,
            'expected_amount': amountFrom,
            'amount_to': amountTo,
            'address_from': self.safe_string(raw, 'address_from'),
            'address_to': self.safe_string(raw, 'address_to'),
            'timestamp': self.safe_string(raw, 'timestamp'),
            'updated_at': self.safe_string(raw, 'updated_at'),
            'info_source': 'website',
        }
        return normalized

    def is_website_order_usable(self, order: dict) -> bool:
        orderId = self.safe_string(order, 'id')
        status = self.safe_string(order, 'status')
        addressFrom = self.safe_string(order, 'address_from')
        return(orderId is not None) and (status is not None) and (addressFrom is not None) and (addressFrom != '')

    def website_order_timestamp_string(self) -> str:
        iso = self.iso8601(self.milliseconds())
        return iso[0:19].replace('T', ' ')

    async def request_website_order(self, id: str, market: Market = None) -> dict:
        self.ensure_website_user_agent()
        pagePart = await self.fetch_website_order_page(id)
        pageWithId = self.extend({'id': id}, pagePart)
        normalized = self.normalize_website_order(pageWithId, market)
        if not self.is_website_order_usable(normalized):
            raise ExchangeError(self.id + ' website order ' + id + ' incomplete')
        return normalized

    async def create_order_via_website_form(self, symbol: str, type: OrderType, side: OrderSide, amount: float, price: Num, params: dict, market: Market) -> Order:
        self.ensure_website_user_agent()
        addressTo = self.safe_string(params, 'address_to')
        refundAddress = self.safe_string(params, 'refund_address', '')
        extraIdTo = self.safe_string(params, 'extra_id_to')
        refundExtraId = self.safe_string(params, 'refund_extra_id')
        if (extraIdTo is not None) or (refundExtraId is not None):
            raise NotSupported(self.id + ' createOrder() website form does not support extra_id/refund_extra_id')
        www = self.safe_string(self.urls, 'www', 'https://www.wizardswap.io')
        homeHtml = await self.fetch(www, 'GET', None, None)
        if not isinstance(homeHtml, str):
            raise InvalidOrder(self.id + ' createOrder() failed: unexpected homepage response')
        csrfToken = self.parse_website_csrf_token(homeHtml)
        estimateResponse = await self.publicPostEstimate({
            'currency_from': market['baseId'],
            'currency_to': market['quoteId'],
            'amount_from': self.number_to_string(amount),
        })
        amountTo = self.safe_string_2(estimateResponse, 'estimated_amount', 'amount_to')
        if amountTo is None:
            raise InvalidOrder(self.id + ' createOrder() failed: estimate missing amount_to')
        formBody = self.urlencode({
            'amount_a': self.number_to_string(amount),
            'crypto_a': market['baseId'].upper(),
            'amount_b': amountTo,
            'crypto_b': market['quoteId'].upper(),
            'refund_address': refundAddress,
            'address': addressTo,
            'token': csrfToken,
            'exchange': 'submit',
        })
        formHeaders = {
            'Content-Type': 'application/x-www-form-urlencoded',
            'Origin': www,
            'Referer': www + '/',
        }
        orderId = None
        try:
            formResponse = await self.fetch(www, 'POST', formHeaders, formBody)
            orderId = self.parse_website_create_order_id(formResponse)
        except Exception as e:
            try:
                orderId = self.parse_website_create_order_id(e)
            except Exception as ignored:
                lastHeaders = self.last_response_headers
                if lastHeaders is not None:
                    locationHeader = self.safe_string_2(lastHeaders, 'Location', 'location')
                    if locationHeader is not None:
                        orderId = self.parse_website_create_order_id(locationHeader)
                    else:
                        raise e
                else:
                    raise e
        rawOrder = await self.request_website_order(orderId, market)
        if self.safe_string(rawOrder, 'timestamp') is None:
            rawOrder['timestamp'] = self.website_order_timestamp_string()
        if self.safe_string(rawOrder, 'address_to') is None:
            rawOrder['address_to'] = addressTo
        return self.parse_order(rawOrder, market)

    async def fetch_order_via_api(self, id: str, params={}) -> Order:
        response = None
        try:
            response = await self.publicPostExchange(self.extend({'id': id}, params))
        except Exception as e:
            raise OrderNotFound(self.id + ' order ' + id + ' not found')
        #
        #  {
        #      "id": "08A75WA1",
        #      "timestamp": "2026-03-24 21:48:22",
        #      "updated_at": "2026-03-24 22:48:22",
        #      "currency_from": "xmr",
        #      "currency_to": "btc",
        #      "amount_from": "0.1000...",
        #      "amount_to": "0.000467720...",
        #      "expected_amount": "0.1000...",
        #      "address_from": "88hsysd...",
        #      "address_to": "1Bitcoin...",
        #      "extra_id_from": "",
        #      "extra_id_to": "",
        #      "tx_from": "",
        #      "tx_to": "",
        #      "status": "waiting",
        #      "refund_address": null,
        #      "refund_extra_id": "",
        #      "currencies": [{"symbol": "xmr", ...}, {"symbol": "btc", ...}]
        #  }
        #
        if response is None or not isinstance(response, dict):
            raise OrderNotFound(self.id + ' order ' + id + ' not found')
        # The API returns a dict with status=null for nonexistent orders
        responseStatus = self.safe_string(response, 'status')
        if responseStatus is None:
            raise OrderNotFound(self.id + ' order ' + id + ' not found')
        return self.parse_order(response)

    async def fetch_currencies(self, params={}) -> Currencies:
        """
        fetches all available currencies on the exchange

        https://www.wizardswap.io/api

        :param dict [params]: extra parameters specific to the exchange API endpoint
        :returns dict: an associative dictionary of currencies
        """
        #
        # GET /api/currency returns an array of currency objects, e.g.:
        #  {
        #      "symbol": "btc",
        #      "has_extra_id": False,
        #      "name": "Bitcoin",
        #      "warnings_from": [],
        #      "warnings_to": [],
        #      "validation_address": "...",
        #      "validation_extra": null,
        #      "address_explorer": null,
        #      "tx_explorer": "https://...",
        #      "image": "https://..."
        #  }
        # Legacy fields(decimals, minamt, enabled, maintenance) may still be parsed when present.
        #
        richResponse = await self.publicGetCurrency(params)
        if isinstance(richResponse, list) and len(richResponse) > 0:
            return self.parse_rich_currencies(richResponse)
        # Last resort: use hardcoded list
        defaultIds = self.safe_list(self.options, 'defaultCurrencyIds', [])
        return self.parse_simple_currencies(defaultIds)

    def parse_rich_currencies(self, response):
        result = {}
        for i in range(0, len(response)):
            entry = response[i]
            rawSymbol = self.safe_string(entry, 'symbol')
            if rawSymbol is None:
                continue
            currencyId = rawSymbol.lower()
            code = self.safe_currency_code(currencyId)
            enabled = self.safe_integer(entry, 'enabled', 1)
            maintenance = self.safe_integer(entry, 'maintenance', 0)
            active = (enabled == 1) and (maintenance == 0)
            decimals = self.safe_integer(entry, 'decimals')
            precision = None
            if decimals is not None:
                precision = self.parse_number(self.parse_precision(self.safe_string(entry, 'decimals')))
            minAmt = self.safe_number(entry, 'minamt')
            result[code] = self.safe_currency_structure({
                'id': currencyId,
                'code': code,
                'name': self.safe_string(entry, 'name'),
                'active': active,
                'deposit': active,
                'withdraw': active,
                'fee': None,
                'precision': precision,
                'limits': {
                    'amount': {'min': minAmt, 'max': None},
                    'withdraw': {'min': minAmt, 'max': None},
                },
                'info': entry,
            })
        return result

    def parse_simple_currencies(self, currencyIds):
        result = {}
        for i in range(0, len(currencyIds)):
            currencyId = currencyIds[i]
            code = self.safe_currency_code(currencyId)
            result[code] = self.safe_currency_structure({
                'id': currencyId,
                'code': code,
                'name': None,
                'active': True,
                'deposit': True,
                'withdraw': True,
                'fee': None,
                'precision': None,
                'limits': {
                    'amount': {'min': None, 'max': None},
                    'withdraw': {'min': None, 'max': None},
                },
                'info': currencyId,
            })
        return result

    async def fetch_markets(self, params={}) -> List[Market]:
        """
        retrieves all available swap pairs from /pairs and /currency

        https://www.wizardswap.io/api

        :param dict [params]: extra parameters specific to the exchange API endpoint
        :returns Market[]: an array of objects representing market data
        """
        currencies = self.safe_dict(self.options, 'cachedCurrencies')
        if not currencies:
            currencies = await self.fetch_currencies(params)
        #
        # GET /api/pairs returns:
        # {
        #     "part": ["pivx","xmr","zec","dash","btc","ltc","eth","firo","zano","bch"],
        #     "xmr":  ["part","pivx","zec","dash","btc","ltc","eth","firo","zano","bch"],
        #     ...
        # }
        #
        pairsData = await self.publicGetPairs(params)
        result = []
        if pairsData is not None and isinstance(pairsData, dict):
            baseIds = list(pairsData.keys())
            for i in range(0, len(baseIds)):
                baseId = baseIds[i]
                baseCode = self.safe_currency_code(baseId)
                quoteIds = self.safe_list(pairsData, baseId, [])
                for j in range(0, len(quoteIds)):
                    quoteId = quoteIds[j]
                    quoteCode = self.safe_currency_code(quoteId)
                    baseCurrency = self.safe_dict(currencies, baseCode, {})
                    quoteCurrency = self.safe_dict(currencies, quoteCode, {})
                    result.append(self.build_market_entry(baseId, quoteId, baseCode, quoteCode, baseCurrency, quoteCurrency))
        else:
            # Fallback: build from currencies(N*(N-1) pairs)
            codes = list(currencies.keys())
            for i in range(0, len(codes)):
                baseCode = codes[i]
                baseCurrency = currencies[baseCode]
                baseId = self.safe_string(baseCurrency, 'id')
                for j in range(0, len(codes)):
                    if i == j:
                        continue
                    quoteCode = codes[j]
                    quoteCurrency = currencies[quoteCode]
                    quoteId = self.safe_string(quoteCurrency, 'id')
                    result.append(self.build_market_entry(baseId, quoteId, baseCode, quoteCode, baseCurrency, quoteCurrency))
        return result

    def build_market_entry(self, baseId, quoteId, baseCode, quoteCode, baseCurrency, quoteCurrency):
        symbol = baseCode + '/' + quoteCode
        baseMinAmt = self.safe_number(self.safe_dict(self.safe_dict(baseCurrency, 'limits', {}), 'amount', {}), 'min')
        return {
            'id': baseId + '_' + quoteId,
            'symbol': symbol,
            'base': baseCode,
            'quote': quoteCode,
            'baseId': baseId,
            'quoteId': quoteId,
            'settle': None,
            'settleId': None,
            'type': 'spot',
            'spot': True,
            'margin': False,
            'swap': False,
            'future': False,
            'option': False,
            'active': True,
            'contract': False,
            'linear': None,
            'inverse': None,
            'contractSize': None,
            'expiry': None,
            'expiryDatetime': None,
            'strike': None,
            'optionType': None,
            'taker': self.parse_number('0.022'),
            'maker': self.parse_number('0.022'),
            'percentage': True,
            'tierBased': False,
            'feeSide': 'get',
            'precision': {
                'amount': self.safe_number(baseCurrency, 'precision'),
                'price': self.safe_number(quoteCurrency, 'precision'),
            },
            'limits': {
                'leverage': {'min': None, 'max': None},
                'amount': {'min': baseMinAmt, 'max': None},
                'price': {'min': None, 'max': None},
                'cost': {'min': None, 'max': None},
            },
            'created': None,
            'info': {
                'baseId': baseId,
                'quoteId': quoteId,
            },
        }

    async def fetch_ticker(self, symbol: str, params={}) -> Ticker:
        """
        fetches a price ticker / estimate for a swap pair

        https://www.wizardswap.io/api

        :param str symbol: unified market symbol, e.g. 'XMR/BTC'
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :param str [params.amount_from]: amount to estimate, defaults to '1'
        :returns dict: a `ticker structure <https://docs.ccxt.com/?id=ticker-structure>`
        """
        await self.load_markets()
        market = self.market(symbol)
        amountFrom = self.safe_string(params, 'amount_from', '1')
        params = self.omit(params, 'amount_from')
        request = {
            'currency_from': market['baseId'],
            'currency_to': market['quoteId'],
            'amount_from': amountFrom,
        }
        response = await self.publicPostEstimate(self.extend(request, params))
        #
        #  {"estimated_amount": "0.00476907"}  (live)
        #  {"amount_to": 0.00476907}             (docs)
        #
        return self.parse_ticker(response, market)

    def parse_ticker(self, ticker: dict, market: Market = None) -> Ticker:
        currencyFrom = self.safe_string(ticker, 'currency_from')
        currencyTo = self.safe_string(ticker, 'currency_to')
        symbol = self.safe_string(market, 'symbol')
        if currencyFrom is not None and currencyTo is not None:
            baseCode = self.safe_currency_code(currencyFrom)
            quoteCode = self.safe_currency_code(currencyTo)
            symbol = baseCode + '/' + quoteCode
        last = self.safe_string_n(ticker, ['estimated_amount', 'amount_to', 'rate'])
        return self.safe_ticker({
            'symbol': symbol,
            'timestamp': None,
            'datetime': None,
            'high': None,
            'low': None,
            'bid': last,
            'bidVolume': None,
            'ask': last,
            'askVolume': None,
            'vwap': None,
            'open': None,
            'close': last,
            'last': last,
            'previousClose': None,
            'change': None,
            'percentage': None,
            'average': None,
            'baseVolume': None,
            'quoteVolume': None,
            'info': ticker,
        }, market)

    async def create_order(self, symbol: str, type: OrderType, side: OrderSide, amount: float, price: Num = None, params={}) -> Order:
        """
        create a swap order on WizardSwap(no API key needed)

        https://www.wizardswap.io/api

        :param str symbol: unified market symbol, e.g. 'XMR/BTC'
        :param str type: order type – only 'market' is supported(floating rate)
        :param str side: 'buy' or 'sell' – for swaps self is always 'sell'(sell base for quote)
        :param float amount: amount of the base currency to send
        :param float [price]: not used for WizardSwap
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :param str params['address_to']: destination address for the quote currency
        :param str [params.refund_address]: refund address for the base currency
        :param str [params.extra_id_to]: recipient Extra ID when the quote currency requires it
        :param str [params.refund_extra_id]: refund Extra ID for the base currency
        :returns dict: an `order structure <https://docs.ccxt.com/?id=order-structure>`
        """
        await self.load_markets()
        market = self.market(symbol)
        addressTo = self.safe_string(params, 'address_to')
        if addressTo is None:
            raise ArgumentsRequired(self.id + ' createOrder() requires params.address_to – the destination address for the received currency')
        if self.website_form_backup_enabled():
            formParams = self.extend({
                'address_to': addressTo,
            }, params)
            return await self.create_order_via_website_form(symbol, type, side, amount, price, formParams, market)
        request = {
            'currency_from': market['baseId'],
            'currency_to': market['quoteId'],
            'amount_from': self.number_to_string(amount),
            'address_to': addressTo,
        }
        refundAddress = self.safe_string(params, 'refund_address')
        if refundAddress is not None:
            request['refund_address'] = refundAddress
        extraIdTo = self.safe_string(params, 'extra_id_to')
        if extraIdTo is not None:
            request['extra_id_to'] = extraIdTo
        refundExtraId = self.safe_string(params, 'refund_extra_id')
        if refundExtraId is not None:
            request['refund_extra_id'] = refundExtraId
        params = self.omit(params, ['address_to', 'refund_address', 'extra_id_to', 'refund_extra_id'])
        # ob_wizardswap enables maxRetriesOnFailure for fetch2(HTTP/network failures only).
        # Missing order id is a successful HTTP response without an id — retry here at createOrder level.
        # Rejected swaps(False) fail immediately; exhausted missing-id retries raise InvalidOrder
        # with a stable message.
        maxRetries = self.safe_integer(self.options, 'maxRetriesOnFailure', 0)
        retryDelay = self.safe_integer(self.options, 'maxRetriesOnFailureDelay', 0)
        extendedRequest = self.extend(request, params)
        for attempt in range(0, maxRetries):
            response = await self.publicPostExchange(extendedRequest)
            if str(response).lower() == 'false':
                raise InvalidOrder(self.id + ' createOrder() failed: exchange returned False(order rejected)')
            orderId = self.safe_string(response, 'id')
            if orderId is not None and orderId != '':
                #
                #  {
                #      "id": "08A75WA1",
                #      "type": "fixed",
                #      "timestamp": "2026-03-24 21:48:22",
                #      "updated_at": "2026-03-24 22:48:21",
                #      "currency_from": "xmr",
                #      "amount_from": "0.1000...",
                #      "expected_amount": "0.1000...",
                #      "amount_to": "0.000467720...",
                #      "address_from": "88hsysd...",
                #      "address_to": "1Bitcoin...",
                #      "extra_id_from": "",
                #      "extra_id_to": "",
                #      "tx_from": "",
                #      "tx_to": "",
                #      "status": "waiting",
                #      "refund_address": null,
                #      "refund_extra_id": "",
                #      "currencies": {...}
                #  }
                #
                # Note: create response may omit currency_to; pass market to parseOrder.
                return self.parse_order(response, market)
            if attempt < maxRetries:
                self.log('createOrder missing id, retrying ...')
                if retryDelay:
                    await self.sleep(retryDelay)
                continue
            raise InvalidOrder(self.id + ' createOrder() failed: exchange response has no order id')
        raise InvalidOrder(self.id + ' createOrder() failed: exchange response has no order id')

    async def fetch_order(self, id: str, symbol: Str = None, params={}) -> Order:
        """
        fetch the status of a WizardSwap exchange/swap order

        https://www.wizardswap.io/api

        :param str id: the order / exchange id
        :param str [symbol]: unified market symbol(optional)
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :returns dict: an `order structure <https://docs.ccxt.com/?id=order-structure>`
        """
        market = None
        if symbol is not None:
            await self.load_markets()
            market = self.market(symbol)
        if self.website_form_backup_enabled():
            try:
                rawOrder = await self.request_website_order(id, market)
                return self.parse_order(rawOrder, market)
            except Exception as e:
                return await self.fetch_order_via_api(id, params)
        return await self.fetch_order_via_api(id, params)

    def parse_order(self, order: dict, market: Market = None) -> Order:
        id = self.safe_string(order, 'id')
        currencyFrom = self.safe_string(order, 'currency_from')
        currencyTo = self.safe_string(order, 'currency_to')
        parsedSymbol = None
        if currencyFrom is not None and currencyTo is not None:
            baseCode = self.safe_currency_code(currencyFrom)
            quoteCode = self.safe_currency_code(currencyTo)
            parsedSymbol = baseCode + '/' + quoteCode
        # Prefer parsed symbol from response, fall back to market
        symbol = parsedSymbol
        if symbol is None:
            symbol = self.safe_string(market, 'symbol')
        rawStatus = self.safe_string(order, 'status')
        status = self.parse_order_status(rawStatus)
        amountFrom = self.safe_string_2(order, 'expected_amount', 'amount_from')
        amountTo = self.safe_string(order, 'amount_to')
        # Parse timestamp from "2026-03-24 21:48:22" format
        timestampStr = self.safe_string(order, 'timestamp')
        timestamp = None
        if timestampStr is not None:
            timestamp = self.parse8601(timestampStr.replace(' ', 'T') + 'Z')
        updatedAtStr = self.safe_string(order, 'updated_at')
        lastUpdateTimestamp = None
        if updatedAtStr is not None:
            lastUpdateTimestamp = self.parse8601(updatedAtStr.replace(' ', 'T') + 'Z')
        return self.safe_order({
            'id': id,
            'clientOrderId': None,
            'info': order,
            'timestamp': timestamp,
            'datetime': self.iso8601(timestamp),
            'lastTradeTimestamp': None,
            'lastUpdateTimestamp': lastUpdateTimestamp,
            'symbol': symbol,
            'type': 'market',
            'timeInForce': None,
            'postOnly': None,
            'side': 'sell',
            'price': amountTo,       # estimated receive amount
            'stopPrice': None,
            'triggerPrice': None,
            'amount': amountFrom,     # amount sent
            'cost': None,
            'average': None,
            'filled': None,
            'remaining': None,
            'status': status,
            'fee': {
                'currency': None,
                'cost': None,
                'rate': self.parse_number('0.022'),
            },
            'trades': None,
        }, market)

    def parse_order_status(self, status: Str) -> Str:
        statuses = self.safe_dict(self.options, 'statusMapping', {})
        return self.safe_string(statuses, status, status)

    def sign(self, path, api='public', method='GET', params={}, headers=None, body=None):
        useOnion = self.safe_bool(self.options, 'useOnion', False)
        baseUrl = self.urls['api']['rest']
        if useOnion:
            baseUrl = self.safe_string(self.options, 'onionUrl', baseUrl)
        url = baseUrl + '/' + self.implode_params(path, params)
        query = self.omit(params, self.extract_params(path))
        if method == 'POST' and self.apiKey and (query['api_key'] is None):
            query['api_key'] = self.apiKey
        if method == 'GET':
            if query:
                url += '?' + self.urlencode(query)
        elif method == 'POST':
            if query:
                body = self.json(query)
                headers = {
                    'Content-Type': 'application/json',
                }
        return {'url': url, 'method': method, 'body': body, 'headers': headers}

    def handle_errors(self, httpCode: int, reason: str, url: str, method: str, headers: dict, body: str, response, requestHeaders, requestBody):
        if response is None:
            return None
        #
        # error responses from WizardSwap:
        #  {"error": "some error message"}
        #
        error = self.safe_string(response, 'error')
        if error is not None:
            raise ExchangeError(self.id + ' ' + error)
        message = self.safe_string(response, 'message')
        if message is not None and httpCode >= 400:
            raise BadRequest(self.id + ' ' + message)
        return None
